// Valida lo que manda el panel (lib/tienda-web/cuenta.ts): { evento: 'tienda_cuenta', solicitud_id }.
// Solo eso: datos y destinatarios se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.solicitud_id, 10);
if (body.evento !== 'tienda_cuenta' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo de una solicitud de cuenta de la tienda web con la fila de "Leer solicitud"
// (tienda_solicitudes_cuenta). Nada viene del webhook (es público): datos y destinatarios los guardó el
// panel (lib/tienda-web/cuenta.ts). Sin fila = ya se mandó o tiene más de un día.
const s = $json;
if (!s || !s.id) return null;

const SEDES = { valencia: 'Valencia', caracas: 'Caracas', panama: 'Panamá' };
const sede = SEDES[s.sede] || s.sede;
const doc = s.sede === 'panama' ? 'RUC' : 'RIF';
const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const para = String(s.destinatarios || '').split(',').map((c) => c.trim()).filter(Boolean);
if (!para.length) return null;

// WhatsApp: 0412… (Venezuela) pasa a 58412…; en Panamá, sin código de país, 507.
let digitos = String(s.telefono || '').replace(/\D/g, '');
if (s.sede !== 'panama' && digitos.startsWith('0')) digitos = '58' + digitos.slice(1);
else if (s.sede === 'panama' && digitos.length <= 8) digitos = '507' + digitos;
const whatsapp = 'https://wa.me/' + digitos;
const nombre = s.nombre + ' ' + s.apellido;

const filas = [
  ['Empresa', s.empresa],
  [doc, s.documento],
  ['Contacto', nombre],
  ['Teléfono', s.telefono],
  ['Correo', s.correo],
  [s.sede === 'panama' ? 'Provincia' : 'Estado', s.estado],
  ['Dirección', s.direccion],
  ['Tipo de negocio', s.tipo_negocio || 'No lo indicó'],
  ['¿Compra al mayor?', Number(s.compra_mayor) ? 'Sí, para una tienda o empresa' : 'No'],
  ...(s.comentario ? [['Comentario', s.comentario]] : []),
];
const asunto = 'Solicitud de cuenta: ' + s.empresa + ' (' + doc + ' ' + s.documento + ') · ' + sede;

const html = '<!doctype html><html><body style="margin:0;background:#F4F5F2;font-family:Arial,Helvetica,sans-serif;color:#0B0D12">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F5F2;padding:24px 12px"><tr><td align="center">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#FFFFFF;border:1px solid #E0E2DB;border-radius:16px">'
  + '<tr><td style="padding:28px 32px 8px"><p style="margin:0;font-size:13px;font-weight:bold;letter-spacing:.06em;color:#1D4ED8">TIENDA WEB · SEDE ' + esc(sede.toUpperCase()) + '</p>'
  + '<h1 style="margin:8px 0 6px;font-size:22px;line-height:1.25">Nueva solicitud de cuenta de distribuidor</h1>'
  + '<p style="margin:0;font-size:15px;line-height:1.5;color:#565C68">' + esc(nombre) + ' pidió una cuenta para <strong style="color:#0B0D12">' + esc(s.empresa) + '</strong>. Verifica los datos y, si procede, crea su cuenta en Odoo y asígnale un vendedor.</p></td></tr>'
  + '<tr><td style="padding:16px 32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #E0E2DB">'
  + filas.map(([k, v]) => '<tr><td style="padding:10px 12px 10px 0;border-bottom:1px solid #E0E2DB;font-size:14px;color:#565C68;width:150px;vertical-align:top">' + esc(k) + '</td><td style="padding:10px 0;border-bottom:1px solid #E0E2DB;font-size:14px;font-weight:bold;vertical-align:top">' + esc(v).replace(/\n/g, '<br>') + '</td></tr>').join('')
  + '</table></td></tr>'
  + '<tr><td style="padding:8px 32px 28px">'
  + '<a href="mailto:' + esc(s.correo) + '" style="display:inline-block;margin:0 8px 8px 0;padding:12px 20px;border-radius:999px;background:#0B0D12;color:#FFFFFF;font-size:14px;font-weight:bold;text-decoration:none">Responder por correo</a>'
  + '<a href="' + esc(whatsapp) + '" style="display:inline-block;margin:0 0 8px;padding:12px 20px;border-radius:999px;background:#25D366;color:#0B0D12;font-size:14px;font-weight:bold;text-decoration:none">Escribir por WhatsApp</a>'
  + '<p style="margin:12px 0 0;font-size:12px;color:#565C68">Solicitud n.º ' + esc(s.id) + ' · ' + esc(s.creado) + ' · Al responder este correo le escribes directamente al cliente.</p>'
  + '</td></tr></table></td></tr></table></body></html>';

const texto = [
  'Nueva solicitud de cuenta de distribuidor · Sede ' + sede,
  '',
  ...filas.map(([k, v]) => k + ': ' + v),
  '',
  'WhatsApp: ' + whatsapp,
  'Solicitud n.º ' + s.id + ' · ' + s.creado,
  'Al responder este correo le escribes directamente al cliente.',
].join('\n');

// MIME multipart/alternative (texto + HTML) para la API de Gmail, con «Responder a» el cliente.
const b64 = (t) => Buffer.from(t, 'utf8').toString('base64');
const partir = (t) => t.replace(/.{1,76}/g, (l) => l + '\r\n');
const asuntoCorto = asunto.slice(0, 200);
const limite = 'tienda-' + s.id + '-' + Date.now().toString(36);
const mime = [
  'From: =?UTF-8?B?' + b64('Tienda web SUPRICOM') + '?= <dmedina@supricom.com.ve>',
  'To: ' + para.join(', '),
  'Reply-To: =?UTF-8?B?' + b64(nombre) + '?= <' + s.correo + '>',
  'Subject: =?UTF-8?B?' + b64(asuntoCorto) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + limite + '"',
  '',
  '--' + limite,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(texto)),
  '--' + limite,
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(html)),
  '--' + limite + '--',
  '',
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { solicitud_id: Number(s.id), para: para.join(', '), asunto: asuntoCorto, raw } };
